prompt --application/deployment/install/install_data_model
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(70316890626548981)
,p_install_id=>wwv_flow_imp.id(70316446271540914)
,p_name=>'data model'
,p_sequence=>10
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- create tables',
'create table expense_report (',
'    id                   number generated by default on null as identity',
'                         constraint expense_report_id_pk primary key,',
'    employee_username    varchar2(100 char) not null,',
'    category             varchar2(25 char) not null constraint expense_report_category_ck',
'                         check (category in (''Meal'',''Hotel'',''Flight'',''Other'')),',
'    expense_date         timestamp with local time zone not null,',
'    description          varchar2(4000 char),',
'    amount               number not null,',
'    status               varchar2(25 char) constraint expense_report_status_ck',
'                         check (status in (''SUBMITTED'',''APPROVED'',''REJECTED'',''PAID'')),',
'    created              timestamp with local time zone not null,',
'    created_by           varchar2(255 char) not null,',
'    updated              timestamp with local time zone not null,',
'    updated_by           varchar2(255 char) not null',
');',
'',
'',
'',
'create table payment_request (',
'    id                   number generated by default on null as identity',
'                         constraint payment_request_id_pk primary key,',
'    employee_username    varchar2(4000 char) not null,',
'    category             varchar2(4000 char) not null,',
'    amount               varchar2(4000 char) not null,',
'    created              timestamp with local time zone not null,',
'    created_by           varchar2(255 char) not null,',
'    updated              timestamp with local time zone not null,',
'    updated_by           varchar2(255 char) not null',
');',
'',
'',
'',
'-- triggers',
'create or replace trigger expense_report_biu',
'    before insert or update',
'    on expense_report',
'    for each row',
'begin',
'    if inserting then',
'        :new.created := sysdate;',
'        :new.created_by := coalesce(sys_context(''APEX$SESSION'',''APP_USER''),user);',
'    end if;',
'    :new.updated := sysdate;',
'    :new.updated_by := coalesce(sys_context(''APEX$SESSION'',''APP_USER''),user);',
'end expense_report_biu;',
'/',
'',
'',
'create or replace trigger payment_request_biu',
'    before insert or update',
'    on payment_request',
'    for each row',
'begin',
'    if inserting then',
'        :new.created := sysdate;',
'        :new.created_by := coalesce(sys_context(''APEX$SESSION'',''APP_USER''),user);',
'    end if;',
'    :new.updated := sysdate;',
'    :new.updated_by := coalesce(sys_context(''APEX$SESSION'',''APP_USER''),user);',
'end payment_request_biu;',
'/',
'',
'',
'-- Generated by Quick SQL 1.2.9 10/16/2025, 12:47:06 PM',
'',
'/*',
'expense_report ',
'    employee_username vc100',
'    category vc25 /check Meal, Hotel, Flight, Other',
'    expense_date date',
'    description vc4000',
'    amount num',
'    status vc25 /check SUBMITTED, APPROVED, REJECTED, PAID',
'',
'payment_request',
'    employee_username',
'    category',
'    amount',
'',
' Non-default options:',
'# settings = {"apex":"Y","auditcols":"Y","date":"TIMESTAMP WITH LOCAL TIME ZONE","db":"19c","pk":"IDENTITY"}',
'',
'*/'))
);
end;
